SELECT lrop.hk_return_order_product AS return_line_hk, lrop.hk_return AS return_hk, lrop.hk_order AS order_hk, lrop.hk_product AS product_hk, loc.hk_customer AS customer_hk, lre.hk_employee AS employee_hk, hr.return_key, ho.order_key, lrop.order_line_number, sr.return_date, cast(date_format(sr.return_date, 'yyyyMMdd') AS INT) AS return_date_key, sr.return_status, sr.return_reason_code, sr.return_quantity, sr.refund_amount, sr.currency_code, sr.load_date AS valid_from, coalesce(sr.load_end_date, timestamp'9999-12-31 23:59:59') AS valid_to, sr.is_current, sr.record_source FROM {processing}.raw_vault.lnk_return_order_product lrop JOIN {processing}.raw_vault.hub_return hr ON hr.hk_return = lrop.hk_return JOIN {processing}.raw_vault.hub_order ho ON ho.hk_order = lrop.hk_order JOIN {processing}.raw_vault.sat_return sr ON sr.hk_return_order_product = lrop.hk_return_order_product LEFT JOIN {processing}.raw_vault.lnk_order_customer loc ON loc.hk_order = lrop.hk_order LEFT JOIN {processing}.raw_vault.lnk_return_employee lre ON lre.hk_return = lrop.hk_return
